<script lang="ts">import {goto}from '$app/navigation';import {createConnection,pipelineErrorMessage,type NexetlError}from '$lib/api/pipelines';import PageHeader from '$lib/components/ui/PageHeader.svelte';import Alert from '$lib/components/ui/Alert.svelte';import ConnectionForm from '$lib/components/connections/ConnectionForm.svelte';let pending=$state(false),error=$state('');async function save(value:Parameters<typeof createConnection>[0]){pending=true;error='';try{const item=await createConnection(value);await goto(`/connections/${item.id}`)}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}</script>
<svelte:head><title>New Connection | NEXETL</title></svelte:head><PageHeader title="New connection" description="Configure a reusable database endpoint. Credentials remain write-only."/>{#if error}<Alert variant="error">{error}</Alert>{/if}<ConnectionForm {pending} onsubmit={save}/>
